  "metadata:\n  name: orders\t-v2\n" -> {metadata:{name:s:"orders-v2"}}
  "bc: 1\nb\tc: 2\n" -> RZ-CFG-002@2:1
  "when: request.method\t== 'GET'\n" -> {when:s:"request.method== 'GET'"}
